import os
import grpc
from concurrent import futures
from google.cloud import firestore

# These modules will be generated by the grpcio-tools compiler
import restaurant_pb2
import restaurant_pb2_grpc

PROJECT_ID = os.environ.get("PROJECT_ID", "cloud-project-512416")
db = firestore.Client(project=PROJECT_ID)

class RestaurantServiceServicer(restaurant_pb2_grpc.RestaurantServiceServicer):
    def GetMenu(self, request, context):
        doc_ref = db.collection('restaurants').document(request.restaurant_id)
        doc = doc_ref.get()
        
        if not doc.exists:
            context.abort(grpc.StatusCode.NOT_FOUND, f"Restaurant {request.restaurant_id} not found")
        
        data = doc.to_dict()
        
        # Map NoSQL document array to gRPC MenuItem objects
        items = []
        for item in data.get('menu', []):
            items.append(restaurant_pb2.MenuItem(
                item_id=item.get('item_id', ''),
                name=item.get('name', ''),
                price=float(item.get('price', 0.0))
            ))
        
        return restaurant_pb2.MenuResponse(
            restaurant_id=request.restaurant_id,
            is_open=data.get('is_open', False),
            items=items
        )

    def UpdateStatus(self, request, context):
        doc_ref = db.collection('restaurants').document(request.restaurant_id)
        # merge=True ensures we don't overwrite the menu array when updating the status
        doc_ref.set({'is_open': request.is_open}, merge=True)
        
        return restaurant_pb2.StatusResponse(success=True)

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    restaurant_pb2_grpc.add_RestaurantServiceServicer_to_server(RestaurantServiceServicer(), server)
    
    # gRPC standard port
    server.add_insecure_port('[::]:50051')
    server.start()
    print("Restaurant gRPC Service started on port 50051")
    
    # Implement Kubernetes liveness probe file
    with open("/tmp/healthy", "w") as f:
        f.write("ok")
        
    server.wait_for_termination()

if __name__ == '__main__':
    serve()